$('jobReport').onclick=()=>{if(!mission)return;const a=document.createElement('a');a.href='/api/inference/report?mission='+mission+(selectedRun?'&run='+selectedRun:'');a.download='inference-report.json';a.click();};
function renderJobs(){const select=$('inferenceRuns');select.replaceChildren(new Option(tr('latest'),''),...jobs.map(j=>new Option(`${tr(j.status)} · ${j.created.slice(0,16)} · ${j.id.slice(0,8)}`,j.id)));select.value=selectedRun;const job=jobs.find(j=>j.id===selectedRun)||jobs[0];activeRun=jobs.find(j=>['queued','running'].includes(j.status))||null;const selected=missions.find(x=>x.id===mission);$('startInference').disabled=!mission||!!activeRun||selected?.input_type!=='images'||selected?.analysis_mode!=='general_traffic';$('inferenceProgress').hidden=!job;$('resumeInference').hidden=true;$('regionSnapshotWarning').hidden=!job?.roi_stale;$('roiRerun').hidden=!job?.roi_review_required||!!activeRun;$('roiRerun').disabled=!!activeRun;if(!job){$('roiRerun').hidden=true;return;}$('inferenceState').textContent=tr(job.status)+' · '+tr(job.stage);$('inferenceBar').max=job.total;$('inferenceBar').value=job.done;$('inferenceText').textContent=`${job.done} / ${job.total} (${Math.round(job.done/job.total*100)}%) · ${job.id}`;$('runError').textContent=job.error||'';$('regionSnapshotWarning').textContent=job.roi_stale?(job.roi_rerun_acknowledgment?`${tr('regionSnapshotRerunTracked')} ${job.roi_rerun_operator} · ${job.roi_rerun_id.slice(0,8)} · ${tr(job.roi_rerun_status)}`:`${tr('regionSnapshotChanged')} ${job.roi_changed_views.map(view=>view.view_name).join(', ')}. ${tr('roiSameInputs')}`):'';$('stopInference').hidden=!activeRun;$('stopInference').disabled=!!activeRun?.stop_requested;$('resumeInference').hidden=!!activeRun||!['failed','cancelled'].includes(job.status)||job.done>=job.total;}
async function poll(){if(!mission||polling)return;polling=true;const current=mission;try{if(missions.find(x=>x.id===mission)?.input_type==='videos'){await refreshVideo();return;}const result=await api('/api/inference?mission='+mission);if(current!==mission)return;const before=JSON.stringify(jobs.map(j=>[j.id,j.done,j.status]));jobs=result;renderJobs();await pollMonitoring();await refreshLearning();if(before!==JSON.stringify(jobs.map(j=>[j.id,j.done,j.status]))&&!dirty&&!loading)await load(true);}catch(e){message(e.message,true);}finally{polling=false;}}
$('startInference').onclick=()=>action(async()=>{if(!leave())return;const result=await api('/api/inference/start',{mission,threshold:Number($('threshold').value),tiled:$('tiled').checked,night_lights:$('nightLights').checked,night_head_id:$('nightHead').value||null});selectedRun=result.run;message(tr('runQueued'));await poll();});
$('roiRerun').onclick=()=>action(async()=>{if(!leave())return;const run=$('inferenceRuns').value||jobs[0]?.id;if(!run)throw new Error(tr('noRunToResume'));const operator=$('operator').value.trim();if(!operator)throw new Error(tr('operator')+' required');const result=await api('/api/inference/roi-rerun',{mission,run,operator});selectedRun=result.run;message(tr('runQueued')+' · '+result.run.slice(0,8));await poll();});
$('stopInference').onclick=()=>action(async()=>{if(activeRun){await api('/api/inference/stop',{mission,run:activeRun.id});await poll();}});$('resumeInference').onclick=()=>action(async()=>{if(!leave())return;const run=$('inferenceRuns').value||jobs[0]?.id;if(!run)throw new Error(tr('noRunToResume'));const result=await api('/api/inference/resume',{mission,run});selectedRun=result.run;await poll();});
for(const id of ['role','status','operator'])$(id).onchange=()=>{if(images[index])dirty=true;};
window.onbeforeunload=e=>{if(dirty){e.preventDefault();e.returnValue='';}};
updateModeOptions();$('inputType').onchange=updateModeOptions;updateRegionControls();translate();loadTimezoneMap();action(async()=>{await refreshMissions();if(missions.length){mission=missions[0].id;$('missions').value=mission;syncMissionConfig();await refreshSchedules();await refreshViews();await load();await poll();}});setInterval(poll,2000);
